from taf.fdsw.rc.interfaces.FDSW18SP.fdsw import FDSW18SP
from taf.fdsw.rc.interfaces.FDSW19.fdsw import FDSW19
from taf.fdsw.rc.interfaces.FDSW19A.fdsw import FDSW19A
from taf.fdsw.rc.interfaces.FDSW20A.fdsw import FDSW20A
from taf.fdsw.rc.interfaces.FDSW20B.fdsw import FDSW20B
from taf.fdsw.rc.interfaces.FDSW21A.fdsw import FDSW21A
from taf.fdsw.rc.interfaces.FDSW21B.fdsw import FDSW21B
from taf.fdsw.rc.interfaces.FDSW21C.fdsw import FDSW21C
from taf.fdsw.rc.interfaces.FDSW21D.fdsw import FDSW21D
from taf.fdsw.rc.interfaces.FDSW21E.fdsw import FDSW21E
from taf.fdsw.rc.interfaces.FDSW21F.fdsw import FDSW21F
from taf.fdsw.rc.interfaces.FDSW22A.fdsw import FDSW22A
from taf.fdsw.rc.interfaces.FDSW22B.fdsw import FDSW22B
from taf.fdsw.rc.interfaces.FDSW23A.fdsw import FDSW23A
from taf.fdsw.rc.interfaces.FDSW23B.fdsw import FDSW23B
from taf.fdsw.rc.interfaces.FDSW23C.fdsw import FDSW23C
from taf.fdsw.rc.interfaces.FDSW23D.fdsw import FDSW23D
from taf.fdsw.rc.interfaces.FDSW24A.fdsw import FDSW24A
from taf.fdsw.rc.interfaces.FDSW24B.fdsw import FDSW24B
from taf.fdsw.rc.interfaces.FDSW24C.fdsw import FDSW24C
from taf.fdsw.rc.interfaces.FDSW25A.fdsw import FDSW25A
from taf.fdsw.rc.interfaces.FDSW25B.fdsw import FDSW25B

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())
logger.setLevel(level='INFO')


class FdswVersionNotSupported(Exception):
    pass


class FdswVersionNotFound(Exception):
    pass


class SupportedFdswVersions():
    fdsw18sp = FDSW18SP
    fdsw18a = FDSW18A
    fdsw19 = FDSW19
    fdsw19a = FDSW19A
    fdsw20a = FDSW20A
    fdsw20b = FDSW20B
    fdsw21a = FDSW21A
    fdsw21b = FDSW21B
    fdsw21c = FDSW21C
    fdsw21d = FDSW21D
    fdsw21e = FDSW21E
    fdsw21f = FDSW21F
    fdsw22a = FDSW22A
    fdsw22b = FDSW22B
    fdsw23a = FDSW23A
    fdsw23b = FDSW23B
    fdsw23c = FDSW23C
    fdsw23d = FDSW23D
    fdsw24a = FDSW24A
    fdsw24b = FDSW24B
    fdsw24c = FDSW24C
    fdsw25a = FDSW25A
    fdsw25b = FDSW25B

    by_latest = (
    FDSW25B, FDSW25A, FDSW24C, FDSW24B, FDSW24A, FDSW23D, FDSW23C, FDSW23B, FDSW23A, FDSW22B, FDSW22A, FDSW21F,
    FDSW21E, FDSW21D, FDSW21C, FDSW21B, FDSW21A, FDSW20B, FDSW20A, FDSW19A, FDSW19, FDSW18A, FDSW18SP)
    latest = by_latest[0]


class FdswProvider():
    @classmethod
    def get_fdsw_interface(cls, fdsw_version, ip_address, port, username, password, secure=True):
        """
        Currently only supports fdsw18sp

        :param fdsw_version: ie fdsw18sp
        :param ip_address:
        :param port:
        :param username:
        :param password:
        :param secure:
        :return:
        """
        if hasattr(SupportedFdswVersions, fdsw_version):
            fdsw_interface = getattr(SupportedFdswVersions, fdsw_version)
            fdsw_obj = fdsw_interface.check_if_supported(ip_address=ip_address, port=port, username=username,
                                                         password=password, secure=secure)
            if fdsw_obj:
                logger.info('Recognized FDSW version as : {}'.format(fdsw_obj.VERSION_NAME))
                return fdsw_obj
            else:
                err_msg = "Requested FDSW version {} is not compatible with rescue console on provided ip address."
                raise FdswVersionNotSupported(err_msg.format(fdsw_version))
        else:
            raise FdswVersionNotSupported("Requested FDSW version {} is not supported.".format(fdsw_version))

    @classmethod
    def discover_fdsw_interface(cls, ip_address, port, username, password, secure=True):
        """
        Starting from latest version of FDSW , discover first available FDSW to operate on.

        :param ip_address:
        :param port:
        :param username:
        :param password:
        :param secure:
        :return:
        """
        for fdsw_interface in SupportedFdswVersions.by_latest:
            try:
                fdsw_obj = fdsw_interface.check_if_supported(ip_address=ip_address, port=port, username=username,
                                                             password=password, secure=secure)
                if fdsw_obj:
                    return fdsw_obj
            except Exception as ex:
                logger.debug('Caught an error: {}'.format(ex))
                continue
        logger.info("FDSW version on provided ip address is not supported."
                     "Trying with the most recent version : {}".format(SupportedFdswVersions.latest.VERSION_NAME))
        try:
            fdsw_obj = SupportedFdswVersions.latest
            return fdsw_obj(ip_address, port, username, password, secure)

        except Exception as ex:
            logger.debug('Caught an error: {}'.format(ex))
            raise FdswVersionNotFound("FDSW Rescue Console could not be discovered, is not supported or not reachable.")
